// ── Tune these three ──────────────────────────────────────────
const WORD_OVERLAP   = 0.18; // bigram Jaccard that counts as "similar wording"
const STRUCTURE_HITS = 2;    // how many of the 4 structural signals must match
const HISTORY        = 30;   // how many past posts to compare against
// ──────────────────────────────────────────────────────────────

// Filler phrases that show up when you are on autopilot. Add your own.
const FILLERS = ['actually', 'to be honest', 'here is the thing', 'the truth is',
                 'turns out', 'and then it hit me', 'let me explain'];

const norm = t => String(t || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');

// ⚠️ Character bigrams look tempting but they are wrong for languages with
// spaces: any two English paragraphs share roughly a third of their character
// pairs just from English spelling, so unrelated drafts get flagged. Use word
// bigrams there, and fall back to character bigrams for Chinese / Japanese /
// Thai, which do not put spaces between words.
const bigrams = t => {
  const s = String(t || '').toLowerCase();
  const words = s.match(/[\p{L}\p{N}]+/gu) || [];
  const cjk = (s.match(/[㐀-鿿぀-ヿ฀-๿]/g) || []).length;
  const out = new Set();
  if (cjk > 8 && cjk * 2 > words.join('').length) {
    const chars = norm(t);
    for (let i = 0; i < chars.length - 1; i++) out.add(chars.slice(i, i + 2));
    return out;
  }
  for (let i = 0; i < words.length - 1; i++) out.add(words[i] + ' ' + words[i + 1]);
  return out;
};

const jaccard = (a, b) => {
  const A = bigrams(a), B = bigrams(b);
  if (!A.size || !B.size) return 0;
  let hit = 0; for (const g of A) if (B.has(g)) hit++;
  return hit / (A.size + B.size - hit);
};

// ── The structural signature: four things that make posts feel the same ──
const endingType = t => {
  const last = String(t || '').trim().split('\n').filter(Boolean).slice(-2).join('\n');
  if (/comment|drop a|reply with|dm me|留言/i.test(last))      return 'comment-bait';
  if (/save this|bookmark|screenshot|存起來/i.test(last))       return 'save-this';
  if (/\?$|which one|what about you|你呢/i.test(last.trim()))   return 'question';
  if (/try it|tonight|start with|just do/i.test(last))          return 'call-to-action';
  return 'statement';
};

const signature = t => {
  const lines = String(t || '').split('\n').filter(l => l.trim());
  const paras = String(t || '').split(/\n\s*\n/).filter(p => p.trim()).length;
  const first = lines[0] || '';
  const m = first.match(/^(i|you|we|they|most people|everyone|nobody|here|this|that|\d+)\b/i);
  return {
    opening: (m ? m[1].toLowerCase() : '') + (/[?？]$/.test(first.trim()) ? '?' : ''),
    ending: endingType(t),
    rhythm: (lines.length <= 6 ? 'short' : lines.length <= 12 ? 'medium' : 'long') + '/' + paras,
    fillers: FILLERS.filter(f => String(t || '').toLowerCase().includes(f)).join('|'),
  };
};

const structureHits = (a, b) => {
  const A = signature(a), B = signature(b); const hits = [];
  if (A.opening && A.opening === B.opening) hits.push(`same opening ("${A.opening}…")`);
  if (A.ending !== 'statement' && A.ending === B.ending) hits.push(`same ending type (${A.ending})`);
  if (A.rhythm === B.rhythm) hits.push(`same rhythm (${A.rhythm})`);
  if (A.fillers && A.fillers === B.fillers) hits.push('same filler phrases');
  return hits;
};

// ── Compare ───────────────────────────────────────────────────
const drafts = $('Get drafts marked ready').all().map(i => i.json);
const past = $('Get last 30 published').all().map(i => i.json).slice(-HISTORY);

const out = [];

for (const d of drafts) {
  let worst = null;

  for (const p of past) {
    const overlap = jaccard(d.text, p.text);
    const hits = structureHits(d.text, p.text);

    // ⚠️ Both conditions, on purpose. Two posts that merely share a rhythm are
    // not a problem — plenty of good posts are 14 lines long. It only reads as
    // repetitive when the wording is close AND the shape is the same.
    if (overlap < WORD_OVERLAP) continue;
    if (hits.length < STRUCTURE_HITS) continue;

    if (!worst || overlap > worst.overlap) {
      worst = { overlap, hits, post: p };
    }
  }

  if (worst) {
    const when = worst.post.published_at || 'a previous post';
    const head = String(worst.post.text || '').split('\n')[0].slice(0, 40);
    out.push({
      json: {
        ...d,
        flagged: true,
        newStatus: 'needs rework',
        note: `reads like "${head}…" (${when}): ${worst.hits.join(', ')}, ` +
              `${Math.round(worst.overlap * 100)}% wording overlap`,
      },
    });
  } else {
    out.push({ json: { ...d, flagged: false, newStatus: 'approved', note: '' } });
  }
}

return out;
